import sys
from datetime import date, timedelta

RATE = {"book": 0.5, "dvd": 1.0, "magazine": 0.2}


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def compute_late_days(due, back):
    if back == "-":
        return None
    days_diff = (parse(back) - parse(due)).days
    return max(days_diff - 3, 0)


def main():
    lines = sys.stdin.read().splitlines()
    asof_date = parse(lines[0].split()[1])
    totals = {}
    for line in lines[1:]:
        if not line.strip():
            continue
        member, kind, due_text, back_text = line.split()
        due = parse(due_text)
        back = parse(back_text) if back_text != "-" else None
        moved_due = due
        if due.weekday() == 6:
            moved_due += timedelta(days=1)
        late_days = compute_late_days(moved_due, back)
        if late_days > 0:
            fee = late_days * RATE[kind]
            totals[member] = totals.get(member, 0) + fee
    for member in sorted(totals):
        print(f"{member} {totals[member]:.2f}")
    total_fees = sum(totals.values())
    print(f"total {total_fees:.2f}")


if __name__ == "__main__":
    main()
